import { configureStore } from '@reduxjs/toolkit';
import rootReducer from './rootReducer';

const isProd = process.env.NODE_ENV === 'production';

export const store = configureStore({
  reducer: rootReducer,
  devTools: !isProd,
  middleware: (getDefault) =>
    getDefault({
      serializableCheck: !isProd,
      immutableCheck: !isProd,
    }),
});

const sentryMiddleware = (store) => (next) => (action) => {
  if (action.type.endsWith('/rejected') && window.Sentry) {
    window.Sentry.withScope((scope) => {
      scope.setExtra('action', action);
      scope.setExtra('state', store.getState());
      window.Sentry.captureException(action.payload ?? action.error);
    });
  }
  return next(action);
};

const response = await fetch('/config.json');
const config = await response.json();

export const store = configureStore({
  reducer: rootReducer,
  middleware: (getDefault) =>
    getDefault({ thunk: { extraArgument: config } }),
});
